  border: 0; margin: 0; padding: 1.75rem 0 0.5rem;
  border-top: 1px solid var(--hairline);
  min-width: 0;
}
fieldset:first-of-type { border-top: 0; padding-top: 0; }
legend { font-size: var(--t-lg); font-weight: 620; padding: 0; margin-block-end: 1rem; float: left; width: 100%; }
legend + * { clear: left; }
.legend-note { color: var(--muted); font-size: var(--t-sm); margin-block: -0.5rem 1rem; clear: left; }

.field { margin-block-end: 1.25rem; }
.field > label, .label {
  display: block; font-weight: 580; margin-block-end: 0.3rem;
}
.optional { font-weight: 400; color: var(--muted); }
.hint { display: block; color: var(--muted); font-size: var(--t-sm); margin-block: -0.15rem 0.4rem; }

input[type="text"], input[type="email"], input[type="password"], input[type="url"],
input[type="number"], select {
  display: block; width: 100%;
  min-height: 2.75rem; padding: 0.5rem 0.75rem;
  font: inherit; color: var(--ink);
  background: var(--surface);
  border: 1px solid var(--line); border-radius: var(--radius);
  transition: border-color 150ms var(--ease), box-shadow 150ms var(--ease);
}
input:hover, select:hover { border-color: var(--ink); }
input:focus-visible, select:focus-visible { outline-offset: 1px; }
input::placeholder { color: var(--muted); opacity: 1; }
select { appearance: none; padding-inline-end: 2.25rem;
  background-image: linear-gradient(45deg, transparent 50%, var(--ink) 50%), linear-gradient(135deg, var(--ink) 50%, transparent 50%);
  background-position: calc(100% - 1.1rem) 55%, calc(100% - 0.8rem) 55%;
  background-size: 0.3rem 0.3rem; background-repeat: no-repeat;
}
.input-short { max-width: 12rem; }
.input-num { max-width: 7rem; font-variant-numeric: tabular-nums; }
.mono-input { font-family: var(--mono); font-size: 0.9375rem; }

[aria-invalid="true"] { border-color: var(--danger); box-shadow: inset 0 0 0 1px var(--danger); }

/* Atomic pair: city + postcode */
.pair { display: grid; grid-template-columns: minmax(0, 1fr); gap: 0 1rem; }
@media (min-width: 30rem) { .pair { grid-template-columns: minmax(0, 1fr) 11rem; } }

.check { display: flex; gap: 0.75rem; align-items: flex-start; margin-block-end: 1rem; }
.check input { width: 1.25rem; height: 1.25rem; margin: 0.15rem 0 0; accent-color: var(--accent); flex: none; }
.check label { font-weight: 580; }
.check .hint { margin: 0.1rem 0 0; }
.check-body { min-width: 0; }
.nested { margin: 0.75rem 0 0.25rem; }
.nested[hidden] { display: none; }
.inline-input { display: flex; align-items: center; gap: 0.5rem; }
.inline-input span { color: var(--muted); }

/* ---------- The tally: numbered issues (signature) ---------- */
/* Same number in the summary and on the field it points at. */

.tally {
  display: inline-grid; place-items: center; flex: none;
  min-width: 1.5rem; height: 1.5rem; padding-inline: 0.3rem;
  font: 600 0.75rem/1 var(--mono); font-variant-numeric: tabular-nums;
  color: var(--danger); background: var(--surface);
  border: 1px solid currentColor; border-radius: 4px;
}

.field-error {
  display: flex; align-items: flex-start; gap: 0.5rem;
  color: var(--danger); font-size: var(--t-sm); font-weight: 560;
  margin-block-start: 0.4rem;
}
.field-error:empty { display: none; }
.field-error .tally { margin-block-start: -0.1rem; }

.error-summary {
  border: 1px solid var(--danger); border-radius: 8px;
  background: var(--danger-bg);
  padding: 1rem 1.25rem;
  margin-block-end: 1.75rem;
}
.error-summary:focus-visible { outline-offset: 3px; }
.error-summary h2 { display: flex; align-items: baseline; gap: 0.6rem; font-size: var(--t-md); }
.error-summary .count { font: 700 var(--t-lg)/1 var(--mono); color: var(--danger); font-variant-numeric: tabular-nums; }
.error-summary ul { list-style: none; margin: 0.75rem 0 0; padding: 0; display: grid; gap: 0.4rem; }
.error-summary li { display: flex; gap: 0.6rem; align-items: flex-start; }
.error-summary a { color: var(--danger); font-weight: 560; }
.error-summary a:hover { color: var(--danger-hover); }
.error-summary p { margin-block-start: 0.35rem; }

/* ---------- Save bar ---------- */

.savebar {
  position: sticky; bottom: 0; z-index: var(--z-sticky);
  display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 0.75rem 1rem;
  margin-block-start: 1rem; padding: 0.75rem 0;
  background: var(--bg);
  border-top: 1px solid var(--hairline);
}
.status-line {
  display: flex; align-items: center; gap: 0.5rem;
  font: 500 0.8125rem/1.3 var(--mono); color: var(--muted);
}
.status-line::before {
  content: ""; width: 0.5rem; height: 0.5rem; border-radius: 50%;
  background: var(--line); flex: none;
}
.status-line[data-state="dirty"] { color: var(--ink); }
.status-line[data-state="dirty"]::before { background: var(--accent); }
.status-line[data-state="saved"]::before { background: var(--ok); }
.status-line[data-state="error"] { color: var(--danger); }
.status-line[data-state="error"]::before { background: var(--danger); }
#save-btn { min-width: 9.5rem; }

/* ---------- Help panel ---------- */

.help-panel {
  background: var(--surface);
  border: 1px solid var(--hairline); border-radius: 8px;
  padding: 1.25rem;
  font-size: var(--t-sm);
}
.help-panel[hidden] { display: none; }
.help-head { display: flex; align-items: center; justify-content: space-between; gap: 1rem; margin-block-end: 0.5rem; }
.help-head .btn-quiet { min-height: 2.75rem; min-width: 2.75rem; }
.help-panel section { padding-block: 0.9rem; border-top: 1px solid var(--hairline); }
.help-panel section:first-of-type { border-top: 0; padding-top: 0.25rem; }
.help-panel h3 { font-size: var(--t-sm); margin-block-end: 0.3rem; }
.help-panel p + p { margin-block-start: 0.5rem; }
.help-panel code { font-family: var(--mono); font-size: 0.8125rem; background: var(--bg); padding: 0.05rem 0.3rem; border-radius: 3px; }

/* ---------- Danger zone ---------- */

.danger-zone {
  margin-block-start: 3.5rem;
  border: 1px solid oklch(0.85 0.06 27); border-radius: 8px;
  background: var(--surface);
  padding: 1.25rem;
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 1rem 2rem;
}
.danger-zone div { flex: 1 1 18rem; min-width: 0; }
.danger-zone p { color: var(--muted); margin-block-start: 0.3rem; max-width: 60ch; }

/* ---------- Dialog ---------- */

dialog {
  width: min(32rem, calc(100vw - 2rem));
  max-height: calc(100dvh - 2rem);
  padding: 1.5rem;
  border: 0; border-radius: 10px;
  background: var(--surface); color: var(--ink);
  box-shadow: 0 20px 50px oklch(0.2 0.02 220 / 0.25), 0 2px 6px oklch(0.2 0.02 220 / 0.12);
  opacity: 1; transform: none;
  transition: opacity 180ms var(--ease), transform 180ms var(--ease), overlay 180ms allow-discrete, display 180ms allow-discrete;
}
@starting-style { dialog[open] { opacity: 0; transform: translateY(6px) scale(0.98); } }
dialog::backdrop { background: oklch(0.2 0.02 220 / 0.5); }
dialog h2 { font-size: var(--t-xl); margin-block-end: 0.75rem; overflow-wrap: anywhere; }
dialog ul { margin: 0.75rem 0 1.25rem; padding-inline-start: 1.25rem; display: grid; gap: 0.35rem; }
dialog .confirm-name { font-family: var(--mono); font-weight: 600; background: var(--bg); padding: 0.05rem 0.3rem; border-radius: 3px; overflow-wrap: anywhere; }
.dialog-actions { display: flex; flex-wrap: wrap-reverse; justify-content: flex-end; gap: 0.75rem; margin-block-start: 1.5rem; }
#delete-btn { min-width: 11rem; }

/* ---------- Sign in ---------- */

.auth {
  max-width: 25rem; margin-inline: auto;
  padding: clamp(2rem, 10vh, 6rem) 1rem 3rem;
}
.auth .wordmark { display: inline-block; margin-block-end: 2rem; }
.auth h1 { font-size: var(--t-xl); margin-block-end: 0.4rem; }
.auth h1:focus { outline: none; }
.auth .lede { color: var(--muted); margin-block-end: 1.5rem; }
.auth form .btn-primary { width: 100%; margin-block-start: 0.5rem; }
.auth .below { margin-block-start: 1.25rem; font-size: var(--t-sm); }

.password-wrap { position: relative; }
.password-wrap input { padding-inline-end: 4.75rem; }
.password-wrap button {
