// Workspace settings: validation, explicit save, help panel, delete confirmation.
(function () {
  'use strict';

  var $ = function (id) { return document.getElementById(id); };
  var form = $('settings-form');
  var status = $('save-status');
  var usage = $('notify-usage');

  var required = function (message) {
    return function (v) { return v.trim() ? '' : message; };
  };

  var rules = {
    'workspace-name': function (v) {
      if (!v.trim()) return 'Enter a workspace name';
      if (v.trim().length > 64) return 'Workspace name must be 64 characters or fewer';
      return '';
    },
    'billing-email': function (v) {
      if (!v.trim()) return 'Enter the email address invoices should go to';
      return Tally.isEmail(v) ? '' : 'Enter the billing email in the format name@company.com';
    },
    'legal-name': required('Enter your company legal name, as it should appear on invoices'),
    'vat-id': function (v) {
      return !v.trim() || Tally.isVatId(v) ? '' : 'Enter a VAT ID that starts with a two-letter country code, like DE123456789';
    },
    'address-line1': required('Enter the first line of the billing address'),
    'city': required('Enter the city'),
    'postcode': function (v) {
      if (!v.trim()) return 'Enter the postcode';
      return Tally.isPostcode(v) ? '' : 'Postcode can only contain letters, numbers, spaces and hyphens';
    },
    'country': required('Choose the country for the billing address'),
    'webhook-url': function (v) {
      if (!v.trim()) return '';
      return {
        '': '',
        https: 'Webhook URL must start with https://',
        'private': "Use a public address. Tallyline can't reach localhost or private networks",
        invalid: 'Enter a full webhook URL, like https://api.yourcompany.com/hooks'
      }[Tally.webhookProblem(v)];
    },
    'threshold': function (v) {
      if (!usage.checked) return '';
      return Tally.isWholeInRange(v, 1, 100) ? '' : 'Enter a whole number from 1 to 100 for the usage alert';
    }
  };

  // ---------- Save model: explicit save, dirty state in the save bar ----------

  var snapshot = function () { return new URLSearchParams(new FormData(form)).toString(); };
  var savedState = snapshot();
  var savedName = $('workspace-name').value.trim();
  var lastSaved = '';
  var leaving = false;

  function setStatus(state, text) {
    if (status.dataset.state === state && status.textContent === text) return; // don't re-announce
    status.dataset.state = state;
    status.textContent = text;
  }
  var isDirty = function () { return snapshot() !== savedState; };

  function refreshStatus() {
    if (Tally.isBusy($('save-btn'))) return;
    if (isDirty()) setStatus('dirty', 'Unsaved changes');
    else if (lastSaved) setStatus('saved', 'Saved at ' + lastSaved);
    else setStatus('clean', 'No unsaved changes');
  }
  form.addEventListener('input', refreshStatus);
  form.addEventListener('change', refreshStatus);

  var fields = Tally.wire(form, rules, function (btn) {
    var sending = snapshot();
    Tally.busy(btn, 'Saving…');
    setStatus('saving', 'Saving…');
    // ponytail: no backend yet; this timeout stands in for PATCH /v1/workspace
    setTimeout(function () {
      Tally.idle(btn);
      savedState = sending;
      savedName = $('workspace-name').value.trim();
      document.querySelectorAll('[data-workspace-name], #topbar-workspace').forEach(function (el) {
        el.textContent = savedName;
      });
      lastSaved = new Intl.DateTimeFormat(undefined, { hour: '2-digit', minute: '2-digit' }).format(new Date());
      refreshStatus();
    }, 900);
  });

  window.addEventListener('beforeunload', function (e) {
    if (!leaving && isDirty()) { e.preventDefault(); e.returnValue = ''; }
  });

  // Threshold only applies while usage alerts are on
  function syncThreshold() {
    $('threshold-group').hidden = !usage.checked;
    fields.recheck($('threshold'));
  }
  usage.addEventListener('change', syncThreshold);
  $('threshold-group').hidden = !usage.checked;

  // ---------- Help panel: non-modal, sits beside the form ----------

  var toggle = $('help-toggle');
  var panel = $('help-panel');
  function setHelp(open, returnFocus) {
    panel.hidden = !open;
    toggle.setAttribute('aria-expanded', String(open));
    $('layout').classList.toggle('has-help', open);
    if (!open && returnFocus) toggle.focus();
  }
  toggle.addEventListener('click', function () { setHelp(panel.hidden); });
  $('help-close').addEventListener('click', function () { setHelp(false, true); });
  panel.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') setHelp(false, true);
  });

  // ---------- Delete workspace ----------

  var dialog = $('delete-dialog');
  var confirmInput = $('delete-confirm');
  var deleteBtn = $('delete-btn');

  $('delete-open').addEventListener('click', function () {
    confirmInput.value = '';
    delete confirmInput.dataset.edited;
    Tally.setError(confirmInput, '');
    $('delete-errors').hidden = true;
    dialog.showModal();
  });
  $('delete-cancel').addEventListener('click', function () { dialog.close(); });
  dialog.addEventListener('cancel', function (e) {
    if (Tally.isBusy(deleteBtn)) e.preventDefault(); // Escape can't abandon a delete in flight
  });

  Tally.wire($('delete-form'), {
    'delete-confirm': function (v) {
      if (!v.trim()) return 'Type the workspace name to confirm';
      return v.trim() === savedName ? '' : "That doesn't match. Type the workspace name exactly as shown, including capitals";
    }
  }, function (btn) {
    Tally.busy(btn, 'Deleting…');
    $('delete-cancel').disabled = true;
    // ponytail: stands in for DELETE /v1/workspace
    setTimeout(function () {
      leaving = true;
      location.href = 'signin.html?deleted=1';
    }, 1200);
  });

  // ---------- Demo: settings.html?demo=invalid prefills several bad values ----------

  if (new URLSearchParams(location.search).get('demo') === 'invalid') {
    $('billing-email').value = 'billing@kestrel';
    $('legal-name').value = '';
    $('vat-id').value = '293847561';
    $('postcode').value = '';
    $('webhook-url').value = 'http://localhost:3000/hooks';
    $('threshold').value = '150';
    refreshStatus();
  }
})();

