// Sign in + inline password reset (#reset), sharing the tally error display from forms.js.
(function () {
  'use strict';

  var $ = function (id) { return document.getElementById(id); };

  if (new URLSearchParams(location.search).get('deleted')) $('deleted-notice').hidden = false;

  var emailRule = function (v) {
    if (!v.trim()) return 'Enter your email address';
    return Tally.isEmail(v) ? '' : 'Enter your email in the format name@company.com';
  };

  // ---------- #reset switches views, so the back button works ----------

  function route(moveFocus) {
    var reset = location.hash === '#reset';
    $('signin-view').hidden = reset;
    $('reset-view').hidden = !reset;
    if (reset) {
      $('reset-form').hidden = false;
      $('reset-sent').hidden = true;
      if (!$('reset-email').value) $('reset-email').value = $('email').value;
    }
    if (moveFocus) $(reset ? 'reset-title' : 'signin-title').focus();
  }
  window.addEventListener('hashchange', function () { route(true); });
  route(false);

  // ---------- Show / hide password ----------

  var toggle = $('password-toggle');
  toggle.addEventListener('click', function () {
    var show = toggle.getAttribute('aria-pressed') !== 'true';
    toggle.setAttribute('aria-pressed', String(show));
    $('password').type = show ? 'text' : 'password';
  });

  // ---------- Sign in ----------

  var failed = $('signin-failed');
  $('signin-form').addEventListener('submit', function () { failed.hidden = true; });

  Tally.wire($('signin-form'), {
    'email': emailRule,
    'password': function (v) { return v ? '' : 'Enter your password'; }
  }, function (btn) {
    Tally.busy(btn, 'Signing in…');
    // ponytail: no auth backend yet. A password of 8+ characters signs in; anything shorter
    // gets the "don't match" response so that path can be seen. Email and password are kept.
    setTimeout(function () {
      if ($('password').value.length >= 8) { location.href = 'settings.html'; return; }
      Tally.idle(btn);
      failed.hidden = false;
      failed.focus();
    }, 800);
  });

  // ---------- Reset ----------

  Tally.wire($('reset-form'), { 'reset-email': emailRule }, function (btn) {
    Tally.busy(btn, 'Sending…');
    // ponytail: stands in for POST /v1/password-resets. Same answer whether or not the account exists.
    setTimeout(function () {
      Tally.idle(btn);
      $('reset-form').hidden = true;
      var sent = $('reset-sent');
      sent.textContent = 'If ' + $('reset-email').value.trim() +
        ' has a Tallyline account, we have sent it a link to choose a new password. Check your spam folder if it has not arrived in a few minutes.';
      sent.hidden = false;
    }, 800);
  });
})();

