// node forms.test.js — checks the pure validators in forms.js
const assert = require('assert');
const T = require('./forms.js');

assert(T.isEmail('finance@company.com'));
assert(!T.isEmail('billing@kestrel'));
assert(!T.isEmail('a b@c.com'));

assert(T.isVatId('DE293847561'));
assert(T.isVatId('gb 123 4567 89'));
assert(!T.isVatId('293847561'));
assert(!T.isVatId('DE1'));

assert(T.isPostcode('10119'));
assert(T.isPostcode('SW1A 1AA'));
assert(!T.isPostcode('1'));
assert(!T.isPostcode('10119!'));

assert(T.isWholeInRange('80', 1, 100));
assert(!T.isWholeInRange('150', 1, 100));
assert(!T.isWholeInRange('0', 1, 100));
assert(!T.isWholeInRange('8.5', 1, 100));

